#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>

void usage() {
    printf("*** lz4 v1.10.0 64-bit multithread, by Yann Collet ***\n");
    printf("Usage : \n");
    printf("      executable [arg] [input] [output] \n\n");
    printf("input   : a filename \n");
    printf("          with no FILE, or when FILE is - or stdin, read standard input\n");
    printf("Arguments : \n");
    printf(" -1     : fast compression (default) \n");
    printf(" -12    : slowest compression level \n");
    printf(" -T#    : use # threads for compression (default:0==auto) \n");
    printf(" -d     : decompression (default for .lz4 extension) \n");
    printf(" -f     : overwrite output without prompting \n");
    printf(" -k     : preserve source files(s)  (default) \n");
    printf("--rm    : remove source file(s) after successful de/compression \n");
    printf(" -h/-H  : display help/long help and exit \n\n");
    printf("Advanced arguments :\n");
    printf(" -V     : display Version number and exit \n");
    printf(" -v     : verbose mode \n");
    printf(" -q     : suppress warnings; specify twice to suppress errors too\n");
    printf(" -c     : force write to standard output, even if it is the console\n");
    printf(" -t     : test compressed file integrity\n");
    printf(" -m     : multiple input files (implies automatic output filenames)\n");
    printf(" -r     : operate recursively on directories (sets also -m) \n");
    printf(" -l     : compress using Legacy format (Linux kernel compression)\n");
    printf(" -z     : force compression \n");
    printf(" -D FILE: use FILE as dictionary (compression & decompression)\n");
    printf(" -B#    : cut file into blocks of size # bytes [32+]\n");
    printf("                     or predefined block size [4-7] (default: 7)\n");
    printf(" -BI    : Block Independence (default)\n");
    printf(" -BD    : Block dependency (improves compression ratio)\n");
    printf(" -BX    : enable block checksum (default:disabled)\n");
    printf("--no-frame-crc : disable stream checksum (default:enabled)\n");
    printf("--content-size : compressed frame includes original size (default:not present)\n");
    printf("--list FILE : lists information about .lz4 files (useful for files compressed with --content-size flag)\n");
    printf("--[no-]sparse  : sparse mode (default:enabled on file, disabled on stdout)\n");
    printf("--favor-decSpeed: compressed files decompress faster, but are less compressed \n");
    printf("--fast[=#]: switch to ultra fast compression level (default: 1)\n");
    printf("--best  : same as -12\n");
    printf("Benchmark arguments : \n");
    printf(" -b#    : benchmark file(s), using # compression level (default : 1) \n");
    printf(" -e#    : test all compression levels from -bX to # (default : 1)\n");
    printf(" -i#    : minimum evaluation time in seconds (default : 3s) \n");
}

int main(int argc, char **argv) {
    if (argc < 2) {
        usage();
        return 0;
    }
    // TODO: implement CLI logic
    return 0;
}
EOF
gcc main.c -o executable
./executable
"}

