#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>

typedef uint8_t  BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;

// --- xxhash32 ---
#define PRIME32_1 2654435761U
#define PRIME32_2 2246822519U
#define PRIME32_3 3266489917U
#define PRIME32_4 668265263U
#define PRIME32_5 374761393U

static U32 rotl32(U32 x, int r) {
    return (x << r) | (x >> (32 - r));
}

U32 XXH32(const void* input, size_t len, U32 seed) {
    const BYTE* p = (const BYTE*)input;
    const BYTE* end = p + len;
    U32 h32;

    if (len >= 16) {
        const BYTE* limit = end - 15;
        U32 v1 = seed + PRIME32_1 + PRIME32_2;
        U32 v2 = seed + PRIME32_2;
        U32 v3 = seed + 0;
        U32 v4 = seed - PRIME32_1;

        do {
            v1 += (*(const U32*)p) * PRIME32_2; v1 = rotl32(v1, 13); v1 *= PRIME32_1; p += 4;
            v2 += (*(const U32*)p) * PRIME32_2; v2 = rotl32(v2, 13); v2 *= PRIME32_1; p += 4;
            v3 += (*(const U32*)p) * PRIME32_2; v3 = rotl32(v3, 13); v3 *= PRIME32_1; p += 4;
            v4 += (*(const U32*)p) * PRIME32_2; v4 = rotl32(v4, 13); v4 *= PRIME32_1; p += 4;
        } while (p < limit);

        h32 = rotl32(v1, 1) + rotl32(v2, 7) + rotl32(v3, 12) + rotl32(v4, 18);
    } else {
        h32 = seed + PRIME32_5;
    }

    h32 += (U32)len;

    while (p + 4 <= end) {
        h32 += (*(const U32*)p) * PRIME32_3;
        h32 = rotl32(h32, 17) * PRIME32_4;
        p += 4;
    }
    while (p < end) {
        h32 += (*p) * PRIME32_5;
        h32 = rotl32(h32, 11) * PRIME32_1;
        p++;
    }

    h32 ^= h32 >> 15;
    h32 *= PRIME32_2;
    h32 ^= h32 >> 13;
    h32 *= PRIME32_3;
    h32 ^= h32 >> 16;

    return h32;
}

// --- LZ4 Compression ---
int LZ4_compress_block(const BYTE* src, size_t srcSize, BYTE* dst, size_t dstCapacity) {
    if (srcSize == 0) return 0;

    // Very simple match finder
    const BYTE* ip = src;
    const BYTE* anchor = ip;
    const BYTE* iend = src + srcSize;
    const BYTE* mflimit = iend - 12;
    const BYTE* matchlimit = iend - 5;

    BYTE* op = dst;
    BYTE* oend = dst + dstCapacity;

    U32 hashTable[1 << 14] = {0}; // 16K entries

    while (ip < mflimit) {
        U32 h = (XXH32(ip, 4, 0) >> 18); // Simple hash
        const BYTE* match = src + hashTable[h];
        hashTable[h] = (U32)(ip - src);

        if (match >= src && ip - match < 65536 && memcmp(ip, match, 4) == 0) {
            // Match found
            size_t litLen = (size_t)(ip - anchor);
            size_t matchLen = 4;
            while (ip + matchLen < matchlimit && ip[matchLen] == match[matchLen]) matchLen++;

            // Encode token
            BYTE* token = op++;
            if (litLen >= 15) {
                *token = 0xF0;
                size_t l = litLen - 15;
                while (l >= 255) { *op++ = 255; l -= 255; }
                *op++ = (BYTE)l;
            } else {
                *token = (BYTE)(litLen << 4);
            }

            // Literals
            memcpy(op, anchor, litLen);
            op += litLen;

            // Offset
            U16 offset = (U16)(ip - match);
            memcpy(op, &offset, 2);
            op += 2;

            // Match length
            if (matchLen >= 19) {
                *token |= 0x0F;
                size_t l = matchLen - 19;
                while (l >= 255) { *op++ = 255; l -= 255; }
                *op++ = (BYTE)l;
            } else {
                *token |= (BYTE)(matchLen - 4);
            }

            ip += matchLen;
            anchor = ip;
        } else {
            ip++;
        }
    }

    // Last literals
    size_t litLen = (size_t)(iend - anchor);
    BYTE* token = op++;
    if (litLen >= 15) {
        *token = 0xF0;
        size_t l = litLen - 15;
        while (l >= 255) { *op++ = 255; l -= 255; }
        *op++ = (BYTE)l;
    } else {
        *token = (BYTE)(litLen << 4);
    }
    memcpy(op, anchor, litLen);
    op += litLen;

    return (int)(op - dst);
}

